// @ppm--version--1.2

// CMS theme tokens. Override any of these in a consumer project to re-skin
// the dashboard / sidebar / login without editing component code.
//
// Keep the keys — CmsShell reads them by name. Translucent variants
// (subtle backgrounds, focus rings, hover overlays) are derived at render
// time so changing `primary` / `text` / `danger` cascades automatically.

export type CmsTheme = {
  /** Primary brand colour: active nav highlight, login CTA, focus rings. */
  primary: string;
  /** Slightly darker primary used for hover and gradient ends. */
  primaryHover: string;
  /** Sidebar background. White / very light works on light themes;
   *  near-black works on dark themes — the nav text auto-contrasts via
   *  `text` and `textMuted`. */
  sidebar: string;
  /** Main page background behind cards. */
  background: string;
  /** Primary text colour on light surfaces (also used on the sidebar
   *  when sidebar is light). */
  text: string;
  /** Secondary / muted text — labels, captions, inactive nav items. */
  textMuted: string;
  /** Subtle border colour for cards, dividers, inputs. */
  border: string;
  /** Destructive accent — logout button, delete buttons, error banners. */
  danger: string;
};

// JSK-Fencing-derived defaults (blue / white / grey). Mirrors
// src/styles/cms.css in the JSK project so the CMS feels native there.
const theme: CmsTheme = {
  primary:      "#3B82F6",
  primaryHover: "#2563EB",
  sidebar:      "#ffffff",
  background:   "#f8fafc",
  text:         "#1e293b",
  textMuted:    "#64748b",
  border:       "#e2e8f0",
  danger:       "#dc2626",
};

export default theme;
